"""Editor documentation derived from the same catalog used by checks."""

from collections.abc import Sequence
from typing import Any

from smelt.config.models import ALL_RULES
from smelt.config.schema import config_json_schema as model_json_schema
from smelt.diagnostics.violation import Category
from smelt.rules.base import RuleContract
from smelt.rules.groups import RULE_GROUPS
from smelt.rules.registry import build_rule_set

SCHEMA_COMMENT = (
    "Generated by Smelt. Refresh with `smelt config schema`; not used by the checker."
)
_VALUES = ["error", "warning", "hint", "on", "off"]


def config_json_schema() -> dict[str, Any]:
    schema = model_json_schema()
    schema["$comment"] = SCHEMA_COMMENT
    properties: dict[str, Any] = {}
    codes: dict[str, Any] = {}
    source_properties: dict[str, Any] = {}
    source_codes: dict[str, Any] = {}
    rules = build_rule_set().rules
    for rule in rules:
        doc = rule.explain()
        definition = {
            "type": "string",
            "enum": _VALUES,
            "title": f"{rule.code}: {doc.summary}",
            "description": f"{doc.summary} {doc.rationale} Repair: {doc.fix}",
            "markdownDescription": (
                f"**{rule.code} — {rule.name}**\n\n{doc.summary}\n\n{doc.rationale}"
                f"\n\n**Problem**\n```{doc.example_language}\n{doc.bad}\n```"
                f"\n\n**Preferred**\n```{doc.example_language}\n{doc.good}\n```"
                f"\n\n{doc.fix}\n\nRun `smelt explain {rule.name}` for details."
            ),
            "examples": [rule.default_severity.value],
        }
        properties[rule.name] = definition
        codes[f"^{rule.code}$"] = definition
        if getattr(rule, "scope", "source") == "source":
            source_properties[rule.name] = definition
            source_codes[f"^{rule.code}$"] = definition
    for group in RULE_GROUPS.values():
        definition = {
            "$ref": "#/$defs/BroadRuleSetting",
            "title": f"{group.name}: {group.summary}",
            "description": f"{group.summary} {group.rationale} Members: {', '.join(group.codes)}.",
            "examples": ["warning"],
        }
        properties[group.name] = definition
        source_properties[group.name] = definition
    for family in Category:
        members = [rule for rule in rules if rule.category == family]
        source_members = [
            rule for rule in members if getattr(rule, "scope", "source") == "source"
        ]
        definition = _selection(
            f"{family.value}: every rule in the {family.value} family",
            members,
        )
        properties[family.value] = definition
        if source_members:
            source_properties[family.value] = _selection(
                f"{family.value}: the source rules in the {family.value} family",
                source_members,
            )
    properties[ALL_RULES] = _selection("ALL: every rule in the catalog", rules)
    source_properties[ALL_RULES] = _selection(
        "ALL: every source rule in the catalog",
        [rule for rule in rules if getattr(rule, "scope", "source") == "source"],
    )
    for definition in (*properties.values(), *source_properties.values()):
        definition.pop("type", None)
        definition.pop("enum", None)
        definition.setdefault("$ref", "#/$defs/RuleSetting")
    broad_severity = {"enum": [value for value in _VALUES if value != "on"]}
    schema["$defs"]["BroadRuleSetting"] = {
        "anyOf": [
            broad_severity,
            {
                "$ref": "#/$defs/RuleOverride",
                "properties": {"severity": broad_severity},
            },
        ],
    }
    rule_settings = {
        "type": "object",
        "description": "Enable individual checks by name or SMT code. Families, groups and ALL can disable or cap active rules.",
        "properties": properties,
        "patternProperties": codes,
        "additionalProperties": False,
    }
    schema["$defs"]["RuleSettings"] = rule_settings
    schema["$defs"]["SourceRuleSettings"] = {
        **rule_settings,
        "description": "Enable source rules by name or SMT code. ALL, families and groups disable or cap active source rules. Configure test-file and project rules at project level.",
        "properties": source_properties,
        "patternProperties": source_codes,
    }
    schema["properties"]["rules"] = {"$ref": "#/$defs/RuleSettings"}
    for contract in ("PackageContract", "MemberPackageContract"):
        schema["$defs"][contract]["properties"]["rules"] = {
            "$ref": "#/$defs/SourceRuleSettings"
        }
    return schema


def _selection(title: str, members: Sequence[RuleContract]) -> dict[str, Any]:
    return {
        "$ref": "#/$defs/BroadRuleSetting",
        "title": title,
        "description": (
            f"{title}. Members: {', '.join(rule.name for rule in members)}. "
            "Disable or cap active rules; individual entries take precedence."
        ),
        "examples": ["off"],
    }
